using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace PdfGen.MultiTenant
{
    public sealed class TenantContext
    {
        public string TenantId { get; }
        public string DisplayName { get; }
        public PdfStyleSheet StyleSheet { get; }

        public TenantContext(string tenantId, string displayName, PdfStyleSheet styleSheet)
        {
            TenantId = tenantId ?? throw new ArgumentNullException(nameof(tenantId));
            DisplayName = displayName ?? throw new ArgumentNullException(nameof(displayName));
            StyleSheet = styleSheet ?? throw new ArgumentNullException(nameof(styleSheet));
        }
    }

    public sealed class PdfStyleSheet
    {
        public string FontFamily { get; set; } = "Helvetica";
        public string HeaderTemplate { get; set; } = "";
        public string FooterTemplate { get; set; } = "";
        public string WatermarkText { get; set; } = "";
    }

    public sealed class PdfRenderRequest
    {
        public string DocumentId { get; set; }
        public string TemplateId { get; set; }
        public Dictionary<string, string> Parameters { get; set; } = new();
        public bool UseCache { get; set; } = true;
    }

    public sealed class CacheEntry
    {
        public byte[] PdfBytes { get; set; }
        public DateTime CreatedUtc { get; set; }
        public string TenantId { get; set; }
        public string ETag { get; set; }
    }

    public interface IPdfRenderer
    {
        byte[] Render(string templateContent, Dictionary<string, string> parameters, PdfStyleSheet style);
    }

    public sealed class PdfGenerationService
    {
        private readonly ConcurrentDictionary<string, CacheEntry> _cache = new();
        private readonly IPdfRenderer _renderer;
        private readonly ITemplateStore _templateStore;
        private readonly TimeSpan _cacheTtl = TimeSpan.FromMinutes(30);
        private static readonly AsyncLocal<TenantContext> _currentTenant = new();

        public static TenantContext CurrentTenant
        {
            get => _currentTenant.Value;
            set => _currentTenant.Value = value;
        }

        public PdfGenerationService(IPdfRenderer renderer, ITemplateStore templateStore)
        {
            _renderer = renderer ?? throw new ArgumentNullException(nameof(renderer));
            _templateStore = templateStore ?? throw new ArgumentNullException(nameof(templateStore));
        }

        public async Task<byte[]> GeneratePdfAsync(PdfRenderRequest request)
        {
            var tenant = CurrentTenant ?? throw new InvalidOperationException("No tenant context");
            ValidateRequest(request);

            var cacheKey = ComputeCacheKey(request, tenant);

            if (request.UseCache && TryGetFromCache(cacheKey, tenant.TenantId, out var cached))
            {
                return cached;
            }

            var templateContent = await _templateStore.GetTemplateAsync(tenant.TenantId, request.TemplateId);
            if (templateContent == null)
                throw new InvalidOperationException($"Template {request.TemplateId} not found");

            var pdfBytes = _renderer.Render(templateContent, request.Parameters, tenant.StyleSheet);

            if (request.UseCache)
            {
                StoreInCache(cacheKey, pdfBytes, tenant.TenantId);
            }

            return pdfBytes;
        }

        private string ComputeCacheKey(PdfRenderRequest request, TenantContext tenant)
        {
            var keyBuilder = new StringBuilder();
            keyBuilder.Append(tenant.TenantId);
            keyBuilder.Append(':');
            keyBuilder.Append(request.TemplateId);
            keyBuilder.Append('|');

            if (request.Parameters != null)
            {
                foreach (var kvp in request.Parameters.OrderBy(x => x.Key))
                {
                    keyBuilder.Append(kvp.Key);
                    keyBuilder.Append('=');
                    keyBuilder.Append(kvp.Value);
                    keyBuilder.Append('&');
                }
            }

            using var sha = SHA256.Create();
            var hash = sha.ComputeHash(Encoding.UTF8.GetBytes(keyBuilder.ToString()));
            return Convert.ToBase64String(hash);
        }

        private bool TryGetFromCache(string cacheKey, string tenantId, out byte[] pdfBytes)
        {
            pdfBytes = null;
            if (_cache.TryGetValue(cacheKey, out var entry))
            {
                if (DateTime.UtcNow - entry.CreatedUtc > _cacheTtl)
                {
                    _cache.TryRemove(cacheKey, out _);
                    return false;
                }

                if (entry.TenantId == tenantId)
                {
                    pdfBytes = entry.PdfBytes;
                    return true;
                }
            }
            return false;
        }

        private void StoreInCache(string cacheKey, byte[] pdfBytes, string tenantId)
        {
            var entry = new CacheEntry
            {
                PdfBytes = pdfBytes,
                CreatedUtc = DateTime.UtcNow,
                TenantId = tenantId,
                ETag = Guid.NewGuid().ToString("N")
            };
            _cache[cacheKey] = entry;
        }

        private void ValidateRequest(PdfRenderRequest request)
        {
            if (string.IsNullOrWhiteSpace(request.DocumentId))
                throw new ArgumentException("DocumentId required");
            if (string.IsNullOrWhiteSpace(request.TemplateId))
                throw new ArgumentException("TemplateId required");
            if (request.TemplateId.Contains("..") || request.TemplateId.Contains("/"))
                throw new ArgumentException("Invalid template ID");
        }

        public void InvalidateTenantCache(string tenantId)
        {
            var keysToRemove = _cache.Where(x => x.Value.TenantId == tenantId).Select(x => x.Key).ToList();
            foreach (var key in keysToRemove)
            {
                _cache.TryRemove(key, out _);
            }
        }
    }

    public interface ITemplateStore
    {
        Task<string> GetTemplateAsync(string tenantId, string templateId);
    }

    public sealed class FileTemplateStore : ITemplateStore
    {
        private readonly string _basePath;
        private readonly string _basePathWithSep;

        public FileTemplateStore(string basePath)
        {
            _basePath = Path.GetFullPath(basePath);
            // Ensure a trailing directory separator so prefix comparisons cannot
            // match sibling directories (e.g. "/app/tpl" vs "/app/tpl_evil").
            _basePathWithSep = _basePath.EndsWith(Path.DirectorySeparatorChar.ToString(), StringComparison.Ordinal)
                ? _basePath
                : _basePath + Path.DirectorySeparatorChar;
        }

        public async Task<string> GetTemplateAsync(string tenantId, string templateId)
        {
            if (string.IsNullOrWhiteSpace(tenantId))
                throw new ArgumentException("tenantId required", nameof(tenantId));
            if (string.IsNullOrWhiteSpace(templateId))
                throw new ArgumentException("templateId required", nameof(templateId));

            var safeTenantId = SanitizePath(tenantId);
            var safeTemplateId = SanitizePath(templateId);
            var fullPath = Path.GetFullPath(Path.Combine(_basePath, safeTenantId, safeTemplateId + ".html"));

            // Compare against the base path including a trailing separator to prevent
            // sibling-directory bypasses.
            if (!fullPath.StartsWith(_basePathWithSep, StringComparison.OrdinalIgnoreCase))
                throw new UnauthorizedAccessException("Path traversal detected");

            if (!File.Exists(fullPath))
                return null;

            return await File.ReadAllTextAsync(fullPath);
        }

        private static string SanitizePath(string input)
        {
            return input.Replace("..", "").Replace("/", "").Replace("\\", "");
        }
    }
}
